drawDoor(ctx, d) {
  const p = this.ground(d.b.doorX + 0.5, d.b.doorY + 0.5);
  ctx.save();
  // threshold
  ctx.fillStyle = 'rgba(46,34,23,0.65)';
  diamondPath(ctx, p.x, p.y - TH / 2 + 2, TW - 10, TH - 8);
  ctx.fill();
  ctx.strokeStyle = 'rgba(210,190,150,0.18)';
  ctx.lineWidth = 1;
  diamondPath(ctx, p.x, p.y - TH / 2 + 2, TW - 10, TH - 8);
  ctx.stroke();
  // open door leaf leaning into the room
  const px = p.x - 16, py = p.y - 6;
  ctx.fillStyle = 'rgba(90,63,38,0.95)';
  ctx.beginPath();
  ctx.moveTo(px, py); ctx.lineTo(px + 12, py - 8);
  ctx.lineTo(px + 20, py - 38); ctx.lineTo(px + 9, py - 31);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(30,22,14,0.6)';
  ctx.stroke();
  ctx.fillStyle = 'rgba(214,187,121,0.75)';
  ctx.fillRect(px + 13, py - 20, 2, 2);
  ctx.restore();
}

