      ctx.strokeStyle = `rgba(226,175,90,${0.4 * (1 - life)})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.ellipse(q.x, q.y, r, r * 0.45, 0, 0, 6.3);
      ctx.stroke();
