    if (!this.ctx) return;
    if (!this.rainGain) return;
    const target = (type === 'rain' ? 0.075 : type === 'storm' ? 0.14 : 0) * intensity;
    this.rainGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.6);
  }

